c='p3';B='MẠNG 3'
def PR(tag,title,code,desc,note='',fs=21,ofs=24):
    o=RUN(code)
    return S2(c,B+' · '+tag,title,card('Ý chính',desc)+CODE(code,fs),RES(OUT(o,ofs),'Kết quả chạy Python thật')+(KEY(note) if note else ''))
S=[]
S.append(TITLE('TIN HỌC · MẠNG 3','ĐỊA CHỈ IP, MẠNG CON<br>VÀ BĂNG THÔNG','Địa chỉ IPv4, địa chỉ riêng – công cộng, mặt nạ mạng con, địa chỉ mạng và quảng bá, số host, chia mạng con, tính thời gian truyền (bit – byte), chia sẻ băng thông; mọi phép tính chạy bằng Python.',['IPv4','/26','mạng con','host','Mbps – MB']))
S.append(goals(c,B,['Đọc và viết <b>địa chỉ IPv4</b>; phân biệt <b>riêng</b> và <b>công cộng</b>.','Tính <b>địa chỉ mạng, quảng bá, số host</b> từ IP và mặt nạ (/n).','Kiểm tra hai địa chỉ có <b>cùng mạng con</b> không; chọn <b>mặt nạ</b> cho số thiết bị.','Tính <b>thời gian truyền</b> tệp với <b>Mbps</b> và <b>MB</b> (nhớ 1 byte = 8 bit).','Hiểu <b>băng thông chia sẻ</b>.'],['IPv4, riêng – công cộng','Mặt nạ, mạng con','Số host, chọn mặt nạ','Băng thông','Tự kiểm tra']))
S.append(S2(c,B+' · 1','Địa chỉ IPv4',card('Cấu trúc',P('<b>IPv4</b>: 32 bit, viết thành <b>4 số</b> (0–255) cách nhau dấu chấm: <b>192.168.10.77</b>.','Mỗi số là một <b>byte</b> (8 bit). Tổng 2³² ≈ <b>4,3 tỉ</b> địa chỉ → cạn kiệt → <b>IPv6</b> (128 bit).','Một địa chỉ có hai phần: <b>phần mạng</b> và <b>phần máy (host)</b>; <b>mặt nạ mạng con</b> cho biết ranh giới.')),RES(OUT(RUN("print(2**32)\nprint('{:08b}'.format(192),'{:08b}'.format(168))\nprint(bin(77))"),24),'Python: số địa chỉ, 192 và 168 ở dạng nhị phân')+KEY('Mỗi số 0–255 vì 8 bit biểu diễn <b>2⁸ = 256</b> giá trị.')))
S.append(S2(c,B+' · 1','Địa chỉ riêng (private) và công cộng',card('Dải địa chỉ riêng',T(tr('Dải','Phạm vi',h=True)+tr('<b>10.0.0.0/8</b>','10.0.0.0 – 10.255.255.255')+tr('<b>172.16.0.0/12</b>','172.16.0.0 – <b>172.31</b>.255.255')+tr('<b>192.168.0.0/16</b>','192.168.0.0 – 192.168.255.255'))+P('Địa chỉ <b>riêng</b> dùng trong LAN, <b>không được định tuyến</b> trên Internet; địa chỉ <b>công cộng</b> duy nhất toàn cầu.')),RES(OUT(RUN("import ipaddress\nfor a in ['172.20.5.1','192.169.1.1','172.32.0.1','11.0.0.1']:\n    print(a, ipaddress.ip_address(a).is_private)"),24),'Địa chỉ nào là riêng?')+KEY('<b>172.20.5.1</b> là riêng; 172.32.x.x và 192.169.x.x nằm <b>ngoài</b> dải.')))
S.append(S2(c,B+' · 2','Mặt nạ mạng con và ký hiệu /n',card('Phần mạng và phần máy',P('<b>Mặt nạ</b>: 32 bit có <b>n bit 1</b> ở đầu: <b>/n</b>. Ví dụ <b>/26</b> = 255.255.255.<b>192</b>.','Bit 1 = <b>phần mạng</b>; bit 0 = <b>phần máy</b>.','Số bit 0 là <b>h = 32 − n</b>: mạng có <b>2ʰ</b> địa chỉ, dùng được <b>2ʰ − 2</b> cho thiết bị.')),T(tr('/n','Mặt nạ','Số địa chỉ','Host',h=True)+tr('/24','255.255.255.0','256','254')+tr('/25','255.255.255.128','128','126')+tr('/26','255.255.255.192','64','<b>62</b>')+tr('/27','255.255.255.224','32','<b>30</b>')+tr('/28','255.255.255.240','16','<b>14</b>')+tr('/29','255.255.255.248','8','6'))+KEY('Trừ <b>2</b>: địa chỉ <b>mạng</b> (đầu) và địa chỉ <b>quảng bá</b> (cuối).')))
S.append(PR('2','Tính địa chỉ mạng, quảng bá, số host',"import ipaddress\nn = ipaddress.ip_interface('192.168.10.77/26')\nprint('mặt nạ    :', n.netmask)\nprint('địa chỉ mạng:', n.network.network_address)\nprint('quảng bá  :', n.network.broadcast_address)\nprint('số host   :', n.network.num_addresses - 2)",P('<b>192.168.10.77/26</b>: khối <b>64</b> địa chỉ: 0–63, 64–127, …','77 thuộc khối bắt đầu từ <b>64</b> → địa chỉ mạng <b>192.168.10.64</b>.','Quảng bá = 127; host = <b>62</b>.'),'Đáp án: địa chỉ mạng <b>192.168.10.64</b>, <b>62</b> host.',18,24))
S.append(S2(c,B+' · 2','Cách tính tay: “khối” địa chỉ',card('Ba bước nhanh',STEPS(['Tìm <b>độ lớn khối</b> = 256 − (octet cuối của mặt nạ). Với /26: 256 − 192 = <b>64</b>.','Địa chỉ mạng = <b>bội của 64 không vượt quá</b> octet cuối của IP: 77 → <b>64</b>.','Quảng bá = địa chỉ mạng + 64 − 1 = <b>127</b>; host = 64 − 2 = <b>62</b>.'])),RES(OUT(RUN("for ip in (70,130,77):\n    kh = 64\n    print(ip, '-> khối bắt đầu', ip//kh*kh, ', quảng bá', ip//kh*kh+kh-1)"),24),'Octet cuối 70, 130, 77 với khối 64')+KEY('Máy 192.168.1.130 thuộc khối <b>128–191</b>, khác khối 64–127 của máy 192.168.1.70.')))
S.append(PR('2','Hai địa chỉ có cùng mạng con không? (/28)',"import ipaddress\nm = '255.255.255.240'\nfor a,b in [('192.168.1.130','192.168.1.140'),('192.168.1.140','192.168.1.145'),('192.168.1.129','192.168.1.144'),('192.168.1.130','192.168.1.145')]:\n    na = ipaddress.ip_network(a+'/'+m, strict=False)\n    nb = ipaddress.ip_network(b+'/'+m, strict=False)\n    print(a, b, na==nb)",P('Mặt nạ 240 → khối <b>16</b> địa chỉ: .128–.143, .144–.159, …','Hai địa chỉ cùng mạng con khi <b>cùng khối</b>.'),'Chỉ cặp <b>.130 và .140</b> cùng khối .128–.143.',15,22))
S.append(PR('3','Chọn mặt nạ cho 25 thiết bị',"import math\nn = 25\nfor p in range(30, 20, -1):\n    host = 2**(32-p) - 2\n    if host >= n:\n        print('/%d: %d host' % (p, host)); break",P('Cần <b>host ≥ 25</b>. /28 chỉ có 14; /27 có <b>30</b> ≥ 25.','Chọn mặt nạ <b>dài nhất</b> (ít lãng phí nhất) vẫn đủ: <b>/27 = 255.255.255.224</b>.'),'Đáp án: <b>255.255.255.224 (/27)</b>; /26 có 62 host nên lãng phí.',20,26))
S.append(S2(c,B+' · 3','Chia mạng con',card('Tách một mạng thành nhiều',P('Mượn thêm bit từ phần máy cho phần mạng: <b>/24 → /26</b> chia thành <b>4</b> mạng con, mỗi mạng 64 địa chỉ.','Mục đích <b>phân đoạn mạng</b>: giới hạn xung đột, <b>bảo vệ máy chủ quan trọng</b>, <b>cô lập sự cố</b>.')),RES(OUT(RUN("import ipaddress\nfor s in ipaddress.ip_network('192.168.1.0/24').subnets(new_prefix=26):\n    print(s, 'host', s.num_addresses-2)"),24),'Chia 192.168.1.0/24 thành bốn /26')+KEY('Mỗi bit mượn <b>nhân đôi</b> số mạng con và <b>chia đôi</b> số địa chỉ mỗi mạng.')))
S.append(S2(c,B+' · 4','Băng thông và đơn vị',card('Bit hay byte?',P('<b>Băng thông</b>: lượng dữ liệu truyền được trong một giây, đo bằng <b>bit/s</b>: <b>Mb/s = Mbps</b> (megabit/giây).','<b>Dung lượng tệp</b> đo bằng <b>byte</b>: <b>MB</b> (megabyte). <b>1 byte = 8 bit</b>.','Thời gian = <b>(MB × 8) ÷ Mbps</b> (giây).')),T(tr('Chữ','Nghĩa',h=True)+tr('<b>Mb</b> hoặc Mbps','megabit (bit)')+tr('<b>MB</b>','megabyte (byte)'))+KEY('Bẫy thường gặp: nhầm MB với Mb, quên nhân 8.')))
S.append(PR('4','Tải tệp 50 MB qua 100 Mbps',"mb = 50\nmbps = 100\nbit = mb * 8\nprint('Số megabit =', bit)\nprint('Thời gian  =', bit / mbps, 'giây')",P('50 MB = 50 × 8 = <b>400 Mb</b>.','400 Mb ÷ 100 Mb/s = <b>4 giây</b>.'),'Nhầm bit/byte cho 0,5 hoặc 5 giây là sai.',23,26))
S.append(PR('4','Tải tệp 600 MB và gấp đôi băng thông',"mb = 600\nfor mbps in (100, 200):\n    print(mbps, 'Mbps ->', mb*8/mbps, 'giây')\nprint('chia 4 máy, 100 Mbps:', 600*8/(100/4), 'giây mỗi máy')",P('<b>600 × 8 ÷ 100 = 48 giây</b>; băng thông gấp đôi → <b>24 giây</b> (tỉ lệ nghịch).','Băng thông <b>chia sẻ</b> cho 4 máy: mỗi máy chỉ còn 25 Mbps → chậm gấp 4.'),'Chia sẻ băng thông làm <b>giảm</b> tốc độ mỗi máy.',20,24))
S.append(PR('4','40 học sinh xem video, mỗi luồng 3 Mb/s',"hs, luong = 40, 3\ntong = hs*luong\nprint('Tổng nhu cầu =', tong, 'Mb/s')\nfor ten, mb in [('10BASE-T',10),('Fast Ethernet',100),('Gigabit',1000)]:\n    print(ten, mb, 'đủ' if mb>=tong else 'THIẾU')",P('Tổng nhu cầu = 40 × 3 = <b>120 Mb/s</b>.','Fast Ethernet 100 Mb/s <b>không đủ</b> → chọn <b>Gigabit</b>.'),'Không được chọn theo tốc độ của <b>một</b> luồng (3 Mb/s).',19,24))
S.append(SELF(c,B+' · 5','Tự kiểm tra 1: tính tay /26','Máy 192.168.1.70/26. Tìm địa chỉ mạng, địa chỉ quảng bá, số host, và 192.168.1.130 có cùng mạng không?','',P('Khối 64: 70 thuộc <b>64–127</b>.','Địa chỉ mạng <b>192.168.1.64</b>; quảng bá <b>192.168.1.127</b>; host <b>62</b>.','192.168.1.130 thuộc khối 128–191 → <b>không cùng mạng</b>.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra 2: thời gian truyền','Tệp 450 MB, đường truyền 100 Mb/s. Thời gian truyền?','',P('450 MB = 450 × 8 = 3600 Mb.','3600 ÷ 100 = <b>36 giây</b>.','Kiểm tra bằng Python: %s giây.'%RUN("print(450*8/100)")),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) 192.168.1.70/26 có địa chỉ mạng 192.168.1.64. (b) Mạng /26 dùng tối đa 62 địa chỉ. (c) Quảng bá của mạng đó là 192.168.1.128. (d) 172.32.0.1 là địa chỉ riêng. (e) Tải 600 MB qua 100 Mbps mất 6 giây.','',P('(a) <b>Đúng</b>.','(b) <b>Đúng</b> (64 − 2).','(c) <b>Sai</b>: là 192.168.1.127.','(d) <b>Sai</b>: ngoài dải 172.16–172.31.','(e) <b>Sai</b>: 48 giây.'),20))
